import{_ as a,o as e,c as i,a3 as n}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"质量与生产总览","description":"","frontmatter":{"title":"质量与生产总览"},"headers":[],"relativePath":"ts-ai/quality/index.md","filePath":"ts-ai/quality/index.md","lastUpdated":1786166505000}'),r={name:"ts-ai/quality/index.md"};function s(d,t,l,o,c,h){return e(),i("div",null,[...t[0]||(t[0]=[n(`<h1 id="质量与生产总览" tabindex="-1">质量与生产总览 <a class="header-anchor" href="#质量与生产总览" aria-label="Permalink to &quot;质量与生产总览&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>把已经能跑的 Agent / Nest / RAG·工作流 / 前端 Chat，收成<strong>可证明质量、可控制风险、可观测、可发布</strong>的生产闭环。本模块讲横切治理与门禁；各业务域里的专项测试（如 Graph 路径、RAG 召回）仍归原章，这里负责<strong>怎么挂到全站回归与上线标准</strong>。</p><p>前置：至少完成 <a href="/ts-ai/backend/">服务端工程</a> 与 <a href="/ts-ai/integration/">全栈集成</a> 主线（能创建 Run、推/消费 SSE）；有 RAG 或工作流时再把对应专项测并入门禁。</p><p><strong>怎么读：</strong></p><ol><li>工程测试：单元 → Mock → Nest 集成 → Nuxt E2E（确定性、可 CI）</li><li>评测闭环：<a href="/ts-ai/quality/testing-evaluation/evaluation-datasets">评测数据集</a> → <a href="/ts-ai/quality/testing-evaluation/regression-gates">回归门禁</a></li><li>安全底线：认证授权 → 租户横切 → 工具权限 → Injection / 敏感数据（供应链按需）</li><li>观测：日志 → 要看什么（Trace/指标）→ 怎么接线 → 成本 → 限流降级 → SLO</li><li>发布：Secret → 镜像 → 健康检查 → CI/CD（挂门禁）；灰度 / 扩容 / 恢复为进阶</li><li><strong>LangSmith 评测实验为可选</strong>；生产 Trace 关联另见观测组</li><li>最后用 <a href="/ts-ai/quality/assembly/assembly-recipes-checklist">组装配方与自检</a> 收束</li></ol><h2 id="上岗最小集" tabindex="-1">上岗最小集 <a class="header-anchor" href="#上岗最小集" aria-label="Permalink to &quot;上岗最小集&quot;">​</a></h2><p>上岗先勾这些；勾不完不要跳进「供应链 / 灰度 / LangSmith 实验」等进阶。前端出身读者可直接按 <a href="/ts-ai/appendix/learning/frontend-backend-learning-path">前端出身学习路线</a> 的 F 阶段裁剪清单执行，两处保持同一最小集。</p><h3 id="必读-上线前" tabindex="-1">必读（上线前） <a class="header-anchor" href="#必读-上线前" aria-label="Permalink to &quot;必读（上线前）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>主题</th><th>文章</th></tr></thead><tbody><tr><td>Agent / 工具单测 + Fake</td><td><a href="/ts-ai/quality/testing-evaluation/agent-unit-testing">Agent 单元测试</a>、<a href="/ts-ai/quality/testing-evaluation/model-tool-mocking">模型与工具 Mock</a></td></tr><tr><td>Nest 集成 + Nuxt E2E</td><td><a href="/ts-ai/quality/testing-evaluation/nestjs-integration-testing">NestJS 集成测试</a>、<a href="/ts-ai/quality/testing-evaluation/nuxt-component-e2e-testing">Nuxt 组件与 E2E</a></td></tr><tr><td>评测集 + CI 门禁</td><td><a href="/ts-ai/quality/testing-evaluation/evaluation-datasets">评测数据集</a>、<a href="/ts-ai/quality/testing-evaluation/regression-gates">回归门禁</a>、<a href="/ts-ai/quality/deployment-operations/ci-cd">CI/CD</a></td></tr><tr><td>结构化日志</td><td><a href="/ts-ai/quality/observability-reliability/structured-logging">结构化日志</a></td></tr><tr><td>安全底线</td><td><a href="/ts-ai/quality/security-governance/authentication-authorization">认证与授权</a>、<a href="/ts-ai/quality/security-governance/multi-tenancy-isolation">多租户隔离</a>、<a href="/ts-ai/quality/security-governance/tool-permissions">工具权限</a>、<a href="/ts-ai/quality/security-governance/prompt-injection-defense">Prompt Injection</a></td></tr></tbody></table><h3 id="可选-进阶-有需要再读" tabindex="-1">可选 / 进阶（有需要再读） <a class="header-anchor" href="#可选-进阶-有需要再读" aria-label="Permalink to &quot;可选 / 进阶（有需要再读）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>主题</th><th>文章</th><th>何时</th></tr></thead><tbody><tr><td>Trace / 指标 / OTel</td><td><a href="/ts-ai/quality/observability-reliability/traces-metrics">Traces 与指标</a>、<a href="/ts-ai/quality/observability-reliability/opentelemetry-langsmith">OpenTelemetry 与 LangSmith</a></td><td>已有日志关联 ID，要跨服务排障</td></tr><tr><td>供应链 / 密钥扫描进阶</td><td><a href="/ts-ai/quality/security-governance/dependency-supply-chain-security">依赖与供应链安全</a></td><td>合规或发布流水线要求</td></tr><tr><td>灰度 / 扩容 / 故障恢复</td><td>部署运维组进阶篇</td><td>主路径 CI + 健康检查已绿</td></tr><tr><td>LangSmith 评测实验</td><td><a href="/ts-ai/quality/testing-evaluation/langsmith-evaluation">评测实验与 LangSmith</a></td><td>本地门禁已稳定；平台为增强非替代</td></tr></tbody></table><p>收束勾选：<a href="/ts-ai/quality/assembly/assembly-recipes-checklist">组装配方与能力自检</a>。</p><h2 id="分组地图" tabindex="-1">分组地图 <a class="header-anchor" href="#分组地图" aria-label="Permalink to &quot;分组地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>你在学什么</th><th>优先级</th></tr></thead><tbody><tr><td><a href="/ts-ai/quality/testing-evaluation/">测试与评测</a></td><td>工程测试 + 评测数据集与门禁；LangSmith 实验可选</td><td><strong>必学</strong>（平台可选）</td></tr><tr><td><a href="/ts-ai/quality/security-governance/">安全与治理</a></td><td>认证授权、租户横切、工具 ACL、Injection、审计、供应链</td><td><strong>必学</strong></td></tr><tr><td><a href="/ts-ai/quality/observability-reliability/">可观测性与可靠性</a></td><td>日志、Trace/指标、OTel 接线、成本、限流降级、SLO</td><td><strong>必学</strong></td></tr><tr><td><a href="/ts-ai/quality/deployment-operations/">部署与运维</a></td><td>Secret、镜像、健康检查、CI/CD；灰度/扩容/恢复</td><td><strong>必学</strong> + <strong>进阶</strong></td></tr><tr><td><a href="/ts-ai/quality/assembly/assembly-recipes-checklist">组装配方与能力自检</a></td><td>上线配方与跨组勾选</td><td><strong>必学</strong>（模块末）</td></tr></tbody></table><h2 id="跨章所有权" tabindex="-1">跨章所有权 <a class="header-anchor" href="#跨章所有权" aria-label="Permalink to &quot;跨章所有权&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>本模块讲</th><th>别章讲</th></tr></thead><tbody><tr><td>Agent / 工具单测与 Fake 模型</td><td>测试策略、用例形状、CI 挂载</td><td><code>fakeModel()</code> API → <a href="/ts-ai/foundations/langchain-bridge/model-call-tests">模型调用的 Fake、Mock 与错误测试</a>、<a href="/ts-ai/quality/testing-evaluation/model-tool-mocking">fakeModel() 与 Agent 测试替身</a>；Middleware 钩子 → <a href="/ts-ai/agent/runtime/middleware-guardrails">Guardrails</a></td></tr><tr><td>RAG / 检索回归</td><td>如何并入全站门禁与阈值</td><td>方法细节 → <a href="/ts-ai/knowledge/rag-engineering/rag-testing">RAG 测试</a>、<a href="/ts-ai/knowledge/retrieval/permission-filtering-retrieval-evaluation">权限过滤与检索评测</a></td></tr><tr><td>图路径 / 状态迁移测</td><td>不重讲；门禁可引用其套件</td><td><a href="/ts-ai/workflow/workflow-quality/">工作流质量</a></td></tr><tr><td>模型选型小评测</td><td>生产门禁与在线信号</td><td>任务选型决策 → <a href="/ts-ai/foundations/model/model-selection-evaluation-cost-latency">模型选型、评测、成本与延迟</a></td></tr><tr><td>认证与授权策略</td><td>资源/操作模型、Token 策略、审计要求</td><td>Nest Guard 接线、Context 注入 → <a href="/ts-ai/backend/ai-service/request-context-tenancy">请求 Context</a>；前端带票 → <a href="/ts-ai/integration/interaction-protocols/auth-files-error-protocols">鉴权协议</a></td></tr><tr><td>多租户隔离</td><td>DB/缓存/向量/队列/日志的横切清单与验收</td><td>记忆 Namespace → <a href="/ts-ai/knowledge/memory/tenant-permission-isolation">租户与权限隔离</a></td></tr><tr><td>工具权限 / HITL</td><td>产品级 ACL、高风险确认、审计事件</td><td>钩子实现 → agent Middleware；确认 UX → <a href="/ts-ai/integration/ai-interaction/tool-confirmation-human-loop">工具确认</a></td></tr><tr><td>Prompt Injection</td><td>不可信外部内容 → 工具与数据边界</td><td>Markdown XSS → <a href="/ts-ai/integration/ai-interaction/markdown-code-citations">Markdown、代码与引用</a></td></tr><tr><td>限流、熔断、SLO</td><td>全站策略与用户可见降级</td><td>队列/Redis 基建 → <a href="/ts-ai/backend/data-tasks/">data-tasks</a>；模型 <code>withFallbacks</code> → <a href="/ts-ai/agent/models-output/model-routing-fallbacks">模型路由与回退</a></td></tr><tr><td>LangSmith</td><td>评测实验（可选）vs 生产 Trace 关联（观测组）</td><td>图内可视化辅助 → <a href="/ts-ai/workflow/workflow-quality/trace-visualization">工作流 Trace</a></td></tr><tr><td>优雅关闭 / SSE drain</td><td>进程级存活就绪与取消在途 Run</td><td>SSE 推流 → <a href="/ts-ai/backend/api-realtime/sse-streaming">backend SSE</a>；前端取消 → <a href="/ts-ai/integration/interaction-protocols/cancellation-reconnection-deduplication">取消重连</a></td></tr></tbody></table><h2 id="学习顺序" tabindex="-1">学习顺序 <a class="header-anchor" href="#学习顺序" aria-label="Permalink to &quot;学习顺序&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工程测试（单元 → Mock → Nest → Nuxt E2E）</span></span>
<span class="line"><span>  → 评测数据集 → 回归门禁</span></span>
<span class="line"><span>  → 安全底线（认证 → 租户 → 工具权限 → Injection / 敏感数据）</span></span>
<span class="line"><span>  → 日志 → Trace/指标 → OTel 接线 → 成本 → 限流降级 → SLO</span></span>
<span class="line"><span>  → Secret → Docker → 健康检查 → CI/CD（挂门禁）</span></span>
<span class="line"><span>  →（进阶）灰度 / 扩容 / 故障恢复</span></span>
<span class="line"><span>  →（可选）评测实验与 LangSmith</span></span>
<span class="line"><span>  → 组装配方与自检</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="主路径-门禁先于平台" tabindex="-1">主路径：门禁先于平台 <a class="header-anchor" href="#主路径-门禁先于平台" aria-label="Permalink to &quot;主路径：门禁先于平台&quot;">​</a></h2><p>本手册默认：<strong>先有可重复的 Mock 测试 + 版本化评测集 + CI 阈值</strong>，再考虑 LangSmith 等实验平台。<br> 观测默认：<strong>结构化日志与关联 ID 必达</strong>；OpenTelemetry 接线按环境启用；LangSmith 用于生产 Trace 关联时与「评测实验」文章分开读，避免混成同一件事。</p>`,21)])])}const g=a(r,[["render",s]]);export{p as __pageData,g as default};
